/**
 * ProjectCard — one project tile on the Projects list (#1352).
 *
 * Presentational only: it renders the three facts the story's outcome calls
 * for (name, description, workflow count) and owns no fetching or state.
 *
 * #1353 landed the project-detail route, so the card is now a link — and it is
 * a `<Link>` wrapping the whole tile rather than an `onClick` on the article,
 * exactly as #1352 anticipated. That keeps the tile's native keyboard focus,
 * middle-click and "copy link address" behaviour, none of which a click
 * handler on a non-interactive element would provide.
 */

import { type ReactElement } from "react";
import { Link } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { type Project } from "../api/projects";

export interface ProjectCardProps {
  readonly project: Project;
}

export function ProjectCard({ project }: ProjectCardProps): ReactElement {
  const hasDescription = project.description.trim() !== "";

  return (
    <Link
      // RELATIVE, so it resolves inside the /workflows mount under both router
      // frames — see WorkflowNavShell's module doc-comment.
      to={project.id}
      data-testid="workflow-project-card"
      className="
        flex h-full flex-col gap-cog-2 rounded-lg border border-cog-divider
        bg-cog-surface p-cog-4 transition-colors hover:border-cog-blue-600
        focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
        dark:hover:border-cog-blue-500
      "
    >
      <h3 className="text-heading-sm font-semibold text-cog-text-primary">
        {project.name}
      </h3>

      {/* An empty description still gets a line of text: without it the cards
          in a grid row lose their shared baseline and the count jumps around.
          The placeholder is dimmer than real copy so it still reads as absent
          content rather than as a description literally named "No description". */}
      <p
        className={
          hasDescription
            ? "text-body-sm text-cog-text-secondary"
            : "text-body-sm italic text-cog-text-tertiary"
        }
      >
        {hasDescription
          ? project.description
          : m.workflow_projects_card_no_description()}
      </p>

      <p className="mt-auto text-body-sm text-cog-text-tertiary">
        {m.workflow_projects_card_workflow_count({ count: project.workflowCount })}
      </p>
    </Link>
  );
}


--- frontends/workflow-mfe/src/projects/ProjectWorkflowRow.tsx (128 lines) ---
/**
 * ProjectWorkflowRow — one workflow on the project detail list (#1353).
 *
 * Renders the four facts the story asks for (name, description, last saved,
 * run status) plus its tag chips, and offers Open and Delete.
 *
 * The name is a real `<a href>` into the canvas, not a click handler on the
 * row: it keeps middle-click, cmd-click and "copy link address" working, and
 * it is what makes the row reachable by keyboard without any roving-tabindex
 * machinery. The Delete button sits outside that link — nesting an interactive
 * control inside an anchor is invalid and makes the delete un-clickable in
 * some browsers.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { Button } from "@omnicore-platform/ui";

import { type ProjectWorkflow } from "../api/projects";

export interface ProjectWorkflowRowProps {
  readonly workflow: ProjectWorkflow;
  /** Absolute href into the canvas for this workflow. */
  readonly href: string;
  /** Omitted when the caller may not write to the project (#1355). */
  readonly onDelete?: (workflow: ProjectWorkflow) => void;
}

/**
 * statusLabel — the run status as display copy.
 *
 * The wire form is the proto enum spelling ("WORKFLOW_STATUS_DRAFT"). Mapped
 * through a closed set so an unrecognised value renders as the raw status
 * rather than as blank — a new status added server-side should look
 * unfamiliar, not invisible.
 */
function statusLabel(status: string): string {
  switch (status) {
    case "WORKFLOW_STATUS_DRAFT":
      return m.workflow_status_draft();
    case "WORKFLOW_STATUS_ACTIVE":
      return m.workflow_status_active();
    case "WORKFLOW_STATUS_PAUSED":
      return m.workflow_status_paused();
    case "WORKFLOW_STATUS_ARCHIVED":
      return m.workflow_status_archived();
    default:
      return status;
  }
}

/** Formats an ISO-8601 timestamp for display; empty input renders a dash. */
function formatSaved(iso: string): string {
  if (!iso) return "—";
  const parsed = new Date(iso);
  return Number.isNaN(parsed.getTime()) ? "—" : parsed.toLocaleString();
}

export function ProjectWorkflowRow({
  workflow,
  href,
  onDelete,
}: ProjectWorkflowRowProps): ReactElement {
  const hasDescription = workflow.description.trim() !== "";

  return (
    <li
      data-testid="workflow-project-row"
      className="flex flex-wrap items-start gap-cog-3 border-b border-cog-divider py-cog-3"
    >
      <div className="flex min-w-cog-0 flex-1 flex-col gap-cog-1">
        <a
          href={href}
          className="
            text-body-md font-medium text-cog-blue-700 hover:underline
            dark:text-cog-blue-300
            focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
          "
        >
          {workflow.name}
        </a>

        {hasDescription ? (
          <p className="truncate text-body-sm text-cog-text-secondary">
            {workflow.description}
          </p>
        ) : null}

        {workflow.tags.length > 0 ? (
          <ul className="flex flex-wrap gap-cog-1" aria-label={m.workflow_tags_row_aria()}>
            {workflow.tags.map((tag) => (
              <li
                key={tag}
                className="rounded-pill border border-cog-divider px-cog-2 text-body-sm text-cog-text-tertiary"
              >
                {tag}
              </li>
            ))}
          </ul>
        ) : null}
      </div>

      <span className="text-body-sm text-cog-text-tertiary">
        {m.workflow_project_row_saved({ when: formatSaved(workflow.updatedAt) })}
      </span>

      <span className="text-body-sm text-cog-text-secondary">
        {statusLabel(workflow.status)}
      </span>

      {onDelete ? (
        // Solid danger, not a quiet text link: this destroys a workflow and
        // its run history. The visible label is the bare verb so the column
        // stays scannable, while the accessible name keeps the workflow name
        // — every row would otherwise announce an identical "Delete".
        <Button
          variant="danger"
          size="sm"
          onClick={() => onDelete(workflow)}
          aria-label={m.workflow_project_row_delete({ name: workflow.name })}
        >
          {m.workflow_project_row_delete_label()}
        </Button>
      ) : null}
    </li>
  );
}


--- frontends/workflow-mfe/src/projects/ShareProjectPanel.tsx (335 lines) ---
/**
 * ShareProjectPanel — project sharing (#1355), rendered inline in the project
 * settings route.
 *
 * This was a modal (`ShareProjectDialog`) until it moved into the settings
 * page. Sharing is a setting, not an interruption: it belongs beside the name
 * and description a project owner is already editing, and a dialog forced a
 * second navigation plus a dismiss for what is a routine adjustment. The
 * behaviour is unchanged — same RPCs, same owner invariants, same optimistic
 * reload after each grant.
 *
 * Distinct from `canvas/ShareWorkflowDialog`, which is #1324's link-sharing
 * surface for a single workflow and still runs on mock data. This one is
 * backed by real RPCs: `listProjectMembers` for the roster, `listOrgMembers`
 * for the candidate list, and `setProjectMember` / `removeProjectMember` for
 * the grants.
 *
 * WHAT A GRANT ACTUALLY DOES. A project is visible ONLY to the person who
 * created it and the people listed here — migration 00020 makes owner-or-shared
 * the only SELECT policy on workflow.projects, so an org member with no grant
 * does not see the project in their Projects list at all. Viewer confers read;
 * Editor additionally may rename the project, delete it, and change what is in
 * it. The panel says so in as many words, because this copy previously claimed
 * the opposite ("everyone in your organisation can already open this project")
 * and that was true: 00019 shipped the grant table as a write gate over
 * org-wide reads, so sharing one project appeared to share every project.
 *
 * The owner is rendered but not editable — ownership lives in
 * `projects.created_by`, not in the grant table, and both `SetMember` and
 * `RemoveMember` refuse it server-side (#1355 AC 2). Showing the row without
 * controls is the honest rendering of that: the owner is genuinely on the
 * roster, they are simply not a grant.
 *
 * The wrapping `<section>` carries an accessible name via `aria-labelledby`,
 * which gives it `role="region"` — that is the handle Cypress scopes to now
 * that there is no dialog to scope to.
 */

import { type ReactElement, useCallback, useEffect, useId, useState } from "react";
import { Button } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import {
  listOrgMembers,
  listProjectMembers,
  memberLabel,
  orgMemberLabel,
  removeProjectMember,
  setProjectMember,
  type OrgMember,
  type ProjectMember,
} from "../api/projects";

export interface ShareProjectPanelProps {
  readonly projectId: string;
  readonly projectName: string;
  /** Injectable for tests; defaults to the real roster reads. */
  readonly loadMembers?: (projectId: string) => Promise<readonly ProjectMember[]>;
  readonly loadOrgMembers?: () => Promise<readonly OrgMember[]>;
}

type GrantableRole = "VIEWER" | "EDITOR";

export function ShareProjectPanel({
  projectId,
  projectName,
  loadMembers = listProjectMembers,
  loadOrgMembers = listOrgMembers,
}: ShareProjectPanelProps): ReactElement {
  const [members, setMembers] = useState<readonly ProjectMember[] | null>(null);
  const [candidates, setCandidates] = useState<readonly OrgMember[]>([]);
  const [selectedUserId, setSelectedUserId] = useState("");
  const [role, setRole] = useState<GrantableRole>("VIEWER");
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const headingId = useId();
  const pickerId = useId();
  const roleId = useId();

  const reload = useCallback(async () => {
    const roster = await loadMembers(projectId);
    setMembers(roster);
    return roster;
  }, [loadMembers, projectId]);

  useEffect(() => {
    let alive = true;
    Promise.all([loadMembers(projectId), loadOrgMembers()])
      .then(([roster, org]) => {
        if (!alive) return;
        setMembers(roster);
        setCandidates(org);
        setError(null);
      })
      .catch((err: unknown) => {
        if (!alive) return;
        setMembers([]);
        setError(err instanceof Error ? err.message : "Unknown error");
      });
    return () => {
      alive = false;
    };
  }, [loadMembers, loadOrgMembers, projectId]);

  // Anyone already on the roster is not a candidate to add — including the
  // owner, who can never be granted anything.
  const alreadyShared = new Set((members ?? []).map((x) => x.userId));
  const addable = candidates.filter((c) => !alreadyShared.has(c.userId));

  const handleAdd = useCallback(async () => {
    if (!selectedUserId) return;
    setIsPending(true);
    try {
      await setProjectMember(projectId, selectedUserId, role);
      await reload();
      setSelectedUserId("");
      setError(null);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setIsPending(false);
    }
  }, [projectId, reload, role, selectedUserId]);

  const handleRoleChange = useCallback(
    async (userId: string, next: GrantableRole) => {
      setIsPending(true);
      try {
        await setProjectMember(projectId, userId, next);
        await reload();
        setError(null);
      } catch (err: unknown) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setIsPending(false);
      }
    },
    [projectId, reload],
  );

  const handleRemove = useCallback(
    async (userId: string) => {
      setIsPending(true);
      try {
        await removeProjectMember(projectId, userId);
        await reload();
        setError(null);
      } catch (err: unknown) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setIsPending(false);
      }
    },
    [projectId, reload],
  );

  return (
    <section
      aria-labelledby={headingId}
      className="flex max-w-xl flex-col gap-cog-2 rounded-lg border border-cog-border p-cog-4"
    >
      <h3
        id={headingId}
        className="text-body-md font-semibold text-cog-text-primary"
      >
        {m.workflow_project_share_title({ name: projectName })}
      </h3>
      <p className="text-body-sm text-cog-text-secondary">
        {m.workflow_project_share_description()}
      </p>

      {/* Add a member */}
      <div className="mt-cog-2 flex flex-wrap items-end gap-cog-3">
        <div className="flex min-w-cog-16 flex-1 flex-col gap-cog-1">
          <label
            htmlFor={pickerId}
            className="text-body-sm font-medium text-cog-text-primary"
          >
            {m.workflow_project_share_add_label()}
          </label>
          <select
            id={pickerId}
            value={selectedUserId}
            disabled={isPending || addable.length === 0}
            onChange={(event) => setSelectedUserId(event.target.value)}
            className="
              rounded-md border border-cog-border bg-cog-surface px-cog-3 py-cog-2
              text-body-sm text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          >
            <option value="">
              {addable.length === 0
                ? m.workflow_project_share_no_candidates()
                : m.workflow_project_share_choose_person()}
            </option>
            {addable.map((c) => (
              <option key={c.userId} value={c.userId}>
                {orgMemberLabel(c)}
              </option>
            ))}
          </select>
        </div>

        <div className="flex flex-col gap-cog-1">
          <label
            htmlFor={roleId}
            className="text-body-sm font-medium text-cog-text-primary"
          >
            {m.workflow_project_share_role_label()}
          </label>
          <select
            id={roleId}
            value={role}
            disabled={isPending}
            onChange={(event) => setRole(event.target.value as GrantableRole)}
            className="
              rounded-md border border-cog-border bg-cog-surface px-cog-3 py-cog-2
              text-body-sm text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          >
            <option value="VIEWER">{m.workflow_project_role_viewer()}</option>
            <option value="EDITOR">{m.workflow_project_role_editor()}</option>
          </select>
        </div>

        <Button
          size="sm"
          disabled={isPending || selectedUserId === ""}
          onClick={() => void handleAdd()}
        >
          {m.workflow_project_share_add_submit()}
        </Button>
      </div>

      {error !== null ? (
        <p
          role="alert"
          className="mt-cog-2 text-body-sm text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {error}
        </p>
      ) : null}

      {/* Roster */}
      <h4 className="mt-cog-3 text-body-md font-semibold text-cog-text-primary">
        {m.workflow_project_share_members_heading()}
