/**
 * TagFilterBar — filter a project's workflow list by tag (#1356 step 3).
 *
 * A row of toggle chips rather than a `<select>`: the vocabulary is small by
 * construction (tags are typed by hand, one at a time) and the current filter
 * has to stay visible while the reader scans the filtered list below it.
 *
 * Single-select, deliberately. #1356's journey is "filter by that tag; clearing
 * the filter restores all", and multi-select immediately raises AND-vs-OR,
 * which the story does not answer and the server's single `?tag=` does not
 * express. Re-clicking the active chip clears the filter, which is also what
 * the explicit "All" chip does — two ways to reach it because the second is
 * discoverable and the first is what people try.
 *
 * Implemented on the shared `RadioGroup` primitive, not a hand-rolled
 * `role="radiogroup"` + `aria-checked` cluster: exactly one option is active
 * at a time, which is what a radiogroup means, and Radix supplies the roles,
 * the checked state, the roving tabindex and arrow-key navigation rather than
 * this file re-deriving them.
 *
 * TWO THINGS THE PRIMITIVE DOES NOT GIVE US FOR FREE, and why they are here:
 *
 *   - `RadioGroup.Root`'s `onValueChange` only fires when the value actually
 *     CHANGES (Radix matches native `<input type="radio">` semantics), so it
 *     can never express "re-click the active chip to clear". Each chip
 *     therefore carries its own `onClick` that clears when it is already the
 *     active one; `onValueChange` handles every other click and all keyboard
 *     selection. The two are mutually exclusive by construction — a click on
 *     an inactive chip changes the value (onValueChange fires, the onClick
 *     branch is not taken), a click on the active one does not.
 *   - `""` is the "no filter" value in this component's PROP contract, but it
 *     is a poor radio value (indistinguishable from "nothing selected"), so
 *     the "All" chip carries a sentinel that is translated back to `""` at
 *     the boundary. Callers never see the sentinel.
 */

import { type ReactElement } from "react";
import { RadioGroup } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

export interface TagFilterBarProps {
  readonly tags: readonly string[];
  /** The active tag, or "" for no filter. */
  readonly value: string;
  readonly onChange: (tag: string) => void;
}

/** The "All" chip's radio value — see the module doc-comment. */
const ALL_VALUE = "__tag_filter_all__";

// `focus-visible:outline-0` is load-bearing, not noise: `RadioGroup.Item`'s
// own base classes add the design system's 2px `cog-focus` OUTLINE, and
// `outline-none` (which only sets a transparent outline *style*) does not
// cancel it — `outline-0` is in tailwind-merge's outline-width group, so it
// replaces the primitive's `outline-2` and leaves this chip with the single
// focus ring it has always drawn.
const CHIP_BASE =
  "rounded-pill border px-cog-3 py-cog-1 text-body-sm transition-colors " +
  "focus-visible:outline-none focus-visible:outline-0 focus-visible:ring-2 focus-visible:ring-cog-focus";

// Active chips carry a border AND a weight change, never colour alone.
const CHIP_ACTIVE =
  "border-cog-blue-600 bg-cog-blue-50 font-semibold text-cog-blue-700 " +
  "dark:border-cog-blue-500 dark:bg-transparent dark:text-cog-blue-300";
const CHIP_IDLE =
  "border-cog-divider text-cog-text-secondary hover:text-cog-text-primary";

export function TagFilterBar({
  tags,
  value,
  onChange,
}: TagFilterBarProps): ReactElement | null {
  // No vocabulary, nothing to filter by. Rendering an "All" chip on its own
  // would be a control that cannot do anything.
  if (tags.length === 0) return null;

  return (
    <RadioGroup.Root
      value={value === "" ? ALL_VALUE : value}
      onValueChange={(next) => onChange(next === ALL_VALUE ? "" : next)}
      aria-label={m.workflow_tags_filter_aria()}
      className="flex flex-wrap items-center gap-cog-2"
    >
      <RadioGroup.Item
        value={ALL_VALUE}
        // Already-active re-click: onValueChange cannot fire here.
        onClick={() => {
          if (value === "") onChange("");
        }}
        className={`${CHIP_BASE} ${value === "" ? CHIP_ACTIVE : CHIP_IDLE}`}
      >
        {m.workflow_tags_filter_all()}
      </RadioGroup.Item>
      {tags.map((tag) => {
        const isActive = tag === value;
        return (
          <RadioGroup.Item
            key={tag}
            value={tag}
            // Re-clicking the active chip clears the filter.
            onClick={() => {
              if (isActive) onChange("");
            }}
            className={`${CHIP_BASE} ${isActive ? CHIP_ACTIVE : CHIP_IDLE}`}
          >
            {tag}
          </RadioGroup.Item>
        );
      })}
    </RadioGroup.Root>
  );
}



