/**
 * DeleteProjectDialog — the destructive confirm for #1354.
 *
 * This is NOT the ordinary OK/Cancel confirm `DeleteWorkflowDialog` uses, and
 * the difference is deliberate. Deleting a project CASCADES: migration 00019
 * takes every workflow in it, and 00005 takes those workflows' canvases,
 * executions and run history with them. There is no soft delete anywhere in
 * the workflow schema and no undo, so the blast radius of a mis-click is
 * every graph a team built inside that project.
 *
 * Two guards, both load-bearing:
 *
 *   1. The body states the EXACT number of workflows that will be destroyed,
 *      taken from `workflow_count` on the project the server just returned —
 *      not a number this component counted from a list it happens to be
 *      rendering, which could be a stale or filtered page.
 *   2. The destructive action stays disabled until the project's name is typed
 *      exactly. A confirmation you can dismiss by pressing Enter twice is not
 *      a confirmation for an irreversible cascade; requiring the name forces
 *      the reader to look at WHICH project they are about to destroy.
 *
 * Built on the shared Radix `AlertDialog`, same shape as
 * `DeleteWorkflowDialog`: always-open Root with no Trigger (the caller owns
 * mount), Cancel/Escape routed through `onOpenChange`, both ignored while
 * `isPending` so an in-flight delete cannot be orphaned, and the Action
 * calling `preventDefault()` so the caller closes on success and stays open on
 * failure.
 */

import { type ReactElement, useId, useState } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { AlertDialog } from "@omnicore-platform/ui";

export interface DeleteProjectDialogProps {
  readonly projectName: string;
  /** Workflows the cascade will destroy. Rendered verbatim in the warning. */
  readonly workflowCount: number;
  readonly isPending: boolean;
  /** Set when the delete failed, so the dialog can stay open and explain. */
  readonly error?: string | null;
  readonly onConfirm: () => void;
  readonly onCancel: () => void;
}

export function DeleteProjectDialog({
  projectName,
  workflowCount,
  isPending,
  error = null,
  onConfirm,
  onCancel,
}: DeleteProjectDialogProps): ReactElement {
  const [typedName, setTypedName] = useState("");
  const inputId = useId();
  const errorId = useId();

  // Trimmed, because a trailing space pasted along with the name is not a
  // different project — but NOT case-folded: the point of this gate is that
  // the reader looked at the name, and accepting a different casing weakens
  // that without making the honest path meaningfully easier.
  const nameMatches = typedName.trim() === projectName;
  const canDelete = nameMatches && !isPending;

  return (
    <AlertDialog.Root
      open
      onOpenChange={(next) => {
        if (!next && !isPending) onCancel();
      }}
    >
      <AlertDialog.Content className="w-full max-w-md rounded-xl bg-cog-surface p-cog-6 shadow-cog-e5">
        <AlertDialog.Title className="text-heading-sm font-semibold text-cog-text-primary">
          {m.workflow_project_delete_title({ name: projectName })}
        </AlertDialog.Title>

        <AlertDialog.Description className="mt-cog-2 text-body-sm text-cog-text-secondary">
          {workflowCount > 0
            ? m.workflow_project_delete_body_with_workflows({
                count: workflowCount,
              })
            : m.workflow_project_delete_body_empty()}
        </AlertDialog.Description>

        {/* The irreversibility gets its own line, in the danger palette, so it
            is not something a reader can skim past inside a paragraph. Not
            colour alone: it is also the only bolded sentence here. */}
        <p className="mt-cog-3 text-body-sm font-semibold text-cog-danger-700 dark:text-cog-danger-dark">
          {m.workflow_project_delete_irreversible()}
        </p>

        <div className="mt-cog-4 flex flex-col gap-cog-2">
          <label
            htmlFor={inputId}
            className="text-body-sm font-medium text-cog-text-primary"
          >
            {m.workflow_project_delete_confirm_label({ name: projectName })}
          </label>
          <input
            id={inputId}
            type="text"
            value={typedName}
            autoComplete="off"
            disabled={isPending}
            onChange={(event) => setTypedName(event.target.value)}
            className="
              rounded-md border border-cog-border bg-cog-surface px-cog-3 py-cog-2
              text-body-sm text-cog-text-primary
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus
            "
          />
        </div>

        {error !== null && error !== "" ? (
          <p
            id={errorId}
            role="alert"
            className="mt-cog-3 text-body-sm text-cog-danger-700 dark:text-cog-danger-dark"
          >
            {error}
          </p>
        ) : null}

        <div className="mt-cog-5 flex justify-end gap-cog-3">
          <AlertDialog.Cancel
            disabled={isPending}
            className="px-cog-4 text-body-sm"
          >
            {m.workflow_project_delete_cancel()}
          </AlertDialog.Cancel>
          <AlertDialog.Action
            variant="danger"
            onClick={(event) => {
              // The caller owns the lifecycle: it unmounts this dialog once
              // the delete settles, and leaves it up on failure.
              event.preventDefault();
              if (canDelete) onConfirm();
            }}
            disabled={!canDelete}
            aria-busy={isPending}
            aria-describedby={error ? errorId : undefined}
            className="px-cog-4 text-body-sm"
          >
            {m.workflow_project_delete_confirm()}
          </AlertDialog.Action>
        </div>
      </AlertDialog.Content>
    </AlertDialog.Root>
  );
}


