/**
 * NewProjectDialog — the create-project form behind the Projects list's
 * "New Project" button (#1352).
 *
 * Built on the shared Radix-backed `Dialog` from `@omnicore-platform/ui`,
 * the same shape as `ShareWorkflowDialog`: `Dialog.Root` is always mounted
 * open with no Trigger, the caller owns show/hide by mounting this component,
 * and Escape / overlay dismissal route through `onOpenChange` to `onCancel`.
 *
 * The dialog owns the whole create round-trip rather than just collecting
 * input, because the two failure modes belong next to the fields that caused
 * them: a blank name is reported inline against the name input (and never
 * reaches the network), and a rejected POST keeps the dialog open with the
 * server's message so the user's typing is not thrown away. `onCreated` fires
 * only after the server has accepted the project.
 *
 * No `autoFocus` on the name field: Radix already moves focus into the panel
 * on open and lands on the first focusable element, which is this input, so
 * the prop would add nothing but a jsx-a11y/no-autofocus violation.
 */

import { type FormEvent, type ReactElement, useId, useState } from "react";
import { Button, Dialog, Input, Label } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { createProject, type Project } from "../api/projects";

export interface NewProjectDialogProps {
  /** Called with the created project once the server has accepted it. */
  readonly onCreated: (project: Project) => void;
  /** Called when the user dismisses the dialog without creating anything. */
  readonly onCancel: () => void;
}

export function NewProjectDialog({
  onCreated,
  onCancel,
}: NewProjectDialogProps): ReactElement {
  const nameId = useId();
  const descriptionId = useId();
  const errorId = useId();

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = (event: FormEvent<HTMLFormElement>): void => {
    event.preventDefault();
    if (isSubmitting) return;

    const trimmedName = name.trim();
    if (trimmedName === "") {
      setError(m.workflow_projects_name_required());
      return;
    }

    setIsSubmitting(true);
    setError(null);
    createProject(trimmedName, description.trim())
      .then(onCreated)
      .catch((err: unknown) => {
        setError(
          `${m.workflow_projects_create_error_prefix()}: ${
            err instanceof Error ? err.message : String(err)
          }`,
        );
        setIsSubmitting(false);
      });
  };

  return (
    <Dialog.Root
      open
      onOpenChange={(next) => {
        if (!next) onCancel();
      }}
    >
      <Dialog.Content className="p-cog-6">
        <Dialog.Title className="text-heading-sm font-semibold text-cog-text-primary">
          {m.workflow_projects_new_dialog_title()}
        </Dialog.Title>
        <Dialog.Description className="mt-cog-2 text-body-sm text-cog-text-secondary">
          {m.workflow_projects_new_dialog_description()}
        </Dialog.Description>

        <form className="mt-cog-5 flex flex-col gap-cog-4" onSubmit={handleSubmit}>
          <div className="flex flex-col gap-cog-2">
            <Label htmlFor={nameId}>{m.workflow_projects_name_label()}</Label>
            <Input
              id={nameId}
              value={name}
              maxLength={255}
              // The inline validation message is the input's error text, so it
              // is wired as its description rather than left as loose copy a
              // screen-reader user would only meet by scanning past the field.
              aria-invalid={error !== null ? true : undefined}
              aria-describedby={error !== null ? errorId : undefined}
              placeholder={m.workflow_projects_name_placeholder()}
              onChange={(event) => {
                setName(event.target.value);
                if (error !== null) setError(null);
              }}
            />
          </div>

          <div className="flex flex-col gap-cog-2">
            <Label htmlFor={descriptionId}>
              {m.workflow_projects_description_label()}
            </Label>
            <Input
              id={descriptionId}
              value={description}
              maxLength={1000}
              placeholder={m.workflow_projects_description_placeholder()}
              onChange={(event) => setDescription(event.target.value)}
            />
          </div>

          {error !== null && (
            <p
              id={errorId}
              role="alert"
              className="text-body-sm text-cog-danger-500 dark:text-cog-danger-dark"
            >
              {error}
            </p>
          )}

          <div className="mt-cog-2 flex justify-end gap-cog-3">
            <Button type="button" variant="secondary" onClick={onCancel}>
              {m.workflow_projects_create_cancel()}
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting
                ? m.workflow_projects_create_pending()
                : m.workflow_projects_create_submit()}
            </Button>
          </div>
        </form>
      </Dialog.Content>
    </Dialog.Root>
  );
}


